tolerance = 0.0075

def calc_tr9(tr_data):
    aveRange123 = 0
    aveRange456 = 0
    aveRange789 = 0
    ave123 = 0
    ave456 = 0
    ave789 = 0

    for result in tr_data:
        aveRange123 += max(result[0], result[1], result[2]) - min(result[0], result[1], result[2])
        aveRange456 += max(result[3], result[4], result[5]) - min(result[3], result[4], result[5])
        aveRange789 += max(result[6], result[7], result[8]) - min(result[6], result[7], result[8])
        ave123 += (result[0] + result[1] + result[2]) / 3.0
        ave456 += (result[3] + result[4] + result[5]) / 3.0
        ave789 += (result[6] + result[7] + result[8]) / 3.0

    aveRange123 /= len(tr_data)
    aveRange456 /= len(tr_data)
    aveRange789 /= len(tr_data)
    EV = 3.05 * (aveRange123 + aveRange456 + aveRange789) / 3.0

    ave123 /= len(tr_data)
    ave456 /= len(tr_data)
    ave789 /= len(tr_data)
    xDiff  = max(ave123, ave456, ave789) - min(ave123, ave456, ave789)
    AV = xDiff * 2.7
    RRV = math.sqrt((EV * EV) + (AV * AV))

    reproducibility = (100 * AV * AV) / (2 * RRV * tolerance)
    repeatability = (100 * EV * EV) / (2 * RRV * tolerance)

    return reproducibility + repeatability

for i in range(1, len(data) - 1):
    print(calc_tr9(data[0:i]))
